if abs(cross(lo)) < 1e-12:
    roots.append(lo)
if abs(cross(hi)) < 1e-12:
    roots.append(hi)
for i in range(N):
    a = lo + (hi-lo)*i/N
    b = lo + (hi-lo)*(i+1)/N
    ca, cb = cross(a), cross(b)
    if ca*cb < 0:
        for _ in range(100):
            mid = (a+b)/2
            if cross(a)*cross(mid) <= 0:
                b = mid
            else:
                a = mid
        roots.append((a+b)/2)
# interior roots only counted once; dedupe
uniq = []
for r in sorted(roots):
